<?php
require_once __DIR__.'/../config/config.php'; require_login();
if(!is_admin() && !can('can_mark_paid')){http_response_code(403);exit('Payment permission denied.');}
$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT o.*,t.table_no FROM orders o JOIN restaurant_tables t ON t.id=o.table_id WHERE o.id=?");$s->execute([$id]);$o=$s->fetch();if(!$o)exit('Order not found.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$m=$_POST['method']??'cash';if(!in_array($m,['cash','card','online','other'],true))$m='other';$status=(is_admin() || can('can_complete'))?'completed':'served';
$u=db()->prepare("UPDATE orders SET payment_status='paid',payment_method=?,paid_by_user_id=?,status=? WHERE id=? AND payment_status='unpaid'");$u->execute([$m,user()['id'],$status,$id]);db()->prepare("INSERT INTO audit_logs(user_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)")->execute([user()['id'],'mark_paid','order',(string)$id,'Payment: '.$m]);flash('Order #'.$id.' marked as paid.'.($status==='completed'?' Order completed.':' Order remains served because this staff member does not have Complete Orders permission.'));redirect('admin.php?page=orders');}
?><h1 class="h1">Complete Payment</h1><div class="card" style="max-width:560px"><h2>Order #<?=$o['id']?> · Table <?=e($o['table_no'])?></h2><h2><?=e(currency_symbol())?><?=number_format($o['total'],2)?></h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Payment Method</label><select name="method"><option value="cash">Cash</option><option value="card">Card / POS</option><option value="online">Online (already paid)</option><option value="other">Other</option></select><button class="btn gold" style="margin-top:14px">MARK AS PAID<?= (is_admin() || can('can_complete')) ? ' & COMPLETE' : '' ?></button></form></div>